import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {FormsModule} from '@angular/forms';import {ActivatedRoute,Router,RouterModule} from '@angular/router';import {Subscription} from 'rxjs';import {LegalService} from '../services/legal.service';import {LanguageService} from '../services/language.service';import {SiteTextPipe} from '../home/site-text.pipe';import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';
@Component({standalone:true,imports:[CommonModule,FormsModule,RouterModule,PlatformLayoutComponent,SiteTextPipe],templateUrl:'./legal-page.component.html',styleUrls:['./legal-page.component.scss']})export class LegalPageComponent implements OnInit,OnDestroy{
 catalog:any;labels:any={};errorKey='';name='';adult=false;agreed=false;working=false;saved=false;role='customer';sign=false;receipt:any;private sub?:Subscription;private request=0;
 constructor(private api:LegalService,private route:ActivatedRoute,private router:Router,public language:LanguageService){}
 ngOnInit(){this.sign=this.route.snapshot.data['accept']===true;this.role=this.route.snapshot.queryParamMap.get('role')||'customer';this.sub=this.language.language$.subscribe(()=>{void this.load();});}
 ngOnDestroy(){this.request++;this.sub?.unsubscribe();}
 async load(){const n=++this.request;this.catalog=null;this.agreed=false;this.saved=false;this.receipt=null;this.errorKey='';try{const catalog=await this.api.catalog(this.role);if(n!==this.request)return;this.catalog=catalog;this.labels=catalog.labels;if(this.sign){try{const s=await this.api.status(this.role);if(n!==this.request)return;this.receipt=s.receipt;this.saved=s.accepted;}catch{if(n===this.request)this.errorKey='needLogin';}}}catch{if(n===this.request)this.errorKey='error';}}
 async accept(){if(!this.catalog?.accepting||!this.adult||!this.agreed||this.name.trim().length<2)return;const n=this.request,catalog=this.catalog;this.working=true;this.errorKey='';try{const result=await this.api.accept(catalog,this.name,this.adult);if(n!==this.request)return;this.receipt=result.receipt;this.saved=true;}catch(e:any){if(n===this.request)this.errorKey=e.status===409?'changed':'errorSave';}finally{this.working=false;}}
 continue(){const target=this.route.snapshot.queryParamMap.get('returnUrl')||'/account/profile';void this.router.navigateByUrl(target.startsWith('/')&&!target.startsWith('//')&&!target.startsWith('/account/accept-terms')?target:'/account/profile');}
 async downloadDocument(d:any){if(d.attachment){try{const response=await fetch('/api/legal/files/'+[d.releaseId,d.id,d.language].map(encodeURIComponent).join('/'));if(!response.ok)throw Error('download');const blob=await response.blob();this.download(blob,d.attachment.filename||'conditions.pdf','application/pdf');}catch{this.errorKey='errorDownload';}return;}this.download(d.text+(d.language!=='fr'?'\n\n'+this.labels.referenceTitle+'\n\n'+d.referenceText:''),d.id+'-'+d.language+'-'+d.version+'.txt','text/plain;charset=utf-8');}
 async downloadReceipt(){if(!this.receipt)return;try{this.download(JSON.stringify(await this.api.receipt(this.receipt.bundleHash),null,2),'godirect-acceptation.json','application/json');}catch{this.errorKey='errorDownload';}}
 private download(data:string|Blob,name:string,type:string){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
